-- =====================================================================
-- V1__schema.sql : Sàn bán laptop, Oracle AI Database 26ai Free (23.26)
-- 68 bảng, 7 module. Flyway chạy dưới người dùng LAPSTORE (PDB FREEPDB1).
-- Sinh từ phụ lục 16 của tài liệu thiết kế CSDL; không có khối PL/SQL nên
-- Flyway tách lệnh theo dấu chấm phẩy mặc định.
-- Quy ước:
--   * id NUMBER(19) GENERATED BY DEFAULT AS IDENTITY  -> @GeneratedValue(IDENTITY)
--   * tiền NUMBER(15,2), báo cáo NUMBER(17,2); thời gian TIMESTAMP WITH TIME ZONE (UTC)
--   * chuỗi VARCHAR2(n CHAR); cột TEXT là CLOB; cờ là BOOLEAN (kiểu thật của 23ai trở lên)
--   * shift_template.start_time/end_time lưu chuỗi 'HH:MM' vì Oracle không có kiểu TIME
--   * created_by/updated_by do JPA auditing thêm vào mọi bảng lưu id app_user và KHÔNG có
--     khóa ngoại (tránh vòng phụ thuộc và không chặn xóa mềm người dùng); các cột
--     *_by nghiệp vụ (approved_by, held_by...) thì có khóa ngoại tới app_user
--   * Khóa ngoại tạo ở cuối file, nên thứ tự CREATE TABLE không quan trọng
-- =====================================================================


-- ---------------- Module A: Danh mục, thông số và giá (14 bảng) ----------------

CREATE TABLE brand (
  id NUMBER(19) GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  name VARCHAR2(80 CHAR) NOT NULL,
  logo_url VARCHAR2(255 CHAR),
  is_active BOOLEAN DEFAULT TRUE NOT NULL,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  updated_at TIMESTAMP WITH TIME ZONE,
  created_by NUMBER(19),
  updated_by NUMBER(19),
  CONSTRAINT pk_brand PRIMARY KEY (id),
  CONSTRAINT uq_brand_name UNIQUE (name)
);

CREATE TABLE color (
  id NUMBER(19) GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  name VARCHAR2(50 CHAR) NOT NULL,
  hex_code CHAR(7),
  is_active BOOLEAN DEFAULT TRUE NOT NULL,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  updated_at TIMESTAMP WITH TIME ZONE,
  created_by NUMBER(19),
  updated_by NUMBER(19),
  CONSTRAINT pk_color PRIMARY KEY (id),
  CONSTRAINT uq_color_name UNIQUE (name)
);

CREATE TABLE category (
  id NUMBER(19) GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  parent_id NUMBER(19),
  name VARCHAR2(100 CHAR) NOT NULL,
  slug VARCHAR2(120 CHAR) NOT NULL,
  sort_order NUMBER(10) DEFAULT 0,
  is_active BOOLEAN DEFAULT TRUE NOT NULL,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  updated_at TIMESTAMP WITH TIME ZONE,
  created_by NUMBER(19),
  updated_by NUMBER(19),
  CONSTRAINT pk_category PRIMARY KEY (id),
  CONSTRAINT uq_category_slug UNIQUE (slug)
);

CREATE TABLE product (
  id NUMBER(19) GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  brand_id NUMBER(19) NOT NULL,
  category_id NUMBER(19) NOT NULL,
  name VARCHAR2(200 CHAR) NOT NULL,
  slug VARCHAR2(220 CHAR) NOT NULL,
  series VARCHAR2(80 CHAR),
  release_year NUMBER(5),
  description CLOB,
  thumbnail_url VARCHAR2(255 CHAR),
  status VARCHAR2(15 CHAR) NOT NULL,
  deleted_at TIMESTAMP WITH TIME ZONE,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  updated_at TIMESTAMP WITH TIME ZONE,
  created_by NUMBER(19),
  updated_by NUMBER(19),
  CONSTRAINT pk_product PRIMARY KEY (id),
  CONSTRAINT uq_product_slug UNIQUE (slug),
  CONSTRAINT uq_product_brand_id_name UNIQUE (brand_id, name)
);

CREATE TABLE product_variant (
  id NUMBER(19) GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  product_id NUMBER(19) NOT NULL,
  sku VARCHAR2(60 CHAR) NOT NULL,
  variant_name VARCHAR2(255 CHAR) NOT NULL,
  color_id NUMBER(19) NOT NULL,
  cpu VARCHAR2(100 CHAR) NOT NULL,
  gpu VARCHAR2(100 CHAR),
  ram_gb NUMBER(5) NOT NULL,
  storage_gb NUMBER(10) NOT NULL,
  current_price NUMBER(15,2) NOT NULL,
  warranty_months NUMBER(5) DEFAULT 12 NOT NULL,
  low_stock_threshold NUMBER(10) DEFAULT 3,
  return_window_days NUMBER(5),
  status VARCHAR2(15 CHAR) NOT NULL,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  updated_at TIMESTAMP WITH TIME ZONE,
  created_by NUMBER(19),
  updated_by NUMBER(19),
  CONSTRAINT pk_product_variant PRIMARY KEY (id),
  CONSTRAINT uq_product_variant_sku UNIQUE (sku),
  CONSTRAINT ck_product_variant_current_price CHECK (current_price >= 0),
  CONSTRAINT uq_product_variant_product_id_color_id_cpu_ram_gb_storage_gb UNIQUE (product_id, color_id, cpu, ram_gb, storage_gb)
);

CREATE TABLE product_image (
  id NUMBER(19) GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  product_id NUMBER(19) NOT NULL,
  variant_id NUMBER(19),
  url VARCHAR2(255 CHAR) NOT NULL,
  public_id VARCHAR2(150 CHAR),
  is_primary BOOLEAN DEFAULT FALSE NOT NULL,
  sort_order NUMBER(10) DEFAULT 0,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  updated_at TIMESTAMP WITH TIME ZONE,
  created_by NUMBER(19),
  updated_by NUMBER(19),
  CONSTRAINT pk_product_image PRIMARY KEY (id)
);

CREATE TABLE attribute_group (
  id NUMBER(19) GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  name VARCHAR2(80 CHAR) NOT NULL,
  sort_order NUMBER(10) DEFAULT 0,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  updated_at TIMESTAMP WITH TIME ZONE,
  created_by NUMBER(19),
  updated_by NUMBER(19),
  CONSTRAINT pk_attribute_group PRIMARY KEY (id),
  CONSTRAINT uq_attribute_group_name UNIQUE (name)
);

CREATE TABLE attribute_definition (
  id NUMBER(19) GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  group_id NUMBER(19) NOT NULL,
  code VARCHAR2(60 CHAR) NOT NULL,
  name VARCHAR2(100 CHAR) NOT NULL,
  data_type VARCHAR2(10 CHAR) NOT NULL,
  unit VARCHAR2(20 CHAR),
  applies_to VARCHAR2(10 CHAR) NOT NULL,
  is_filterable BOOLEAN NOT NULL,
  is_comparable BOOLEAN NOT NULL,
  sort_order NUMBER(10),
  is_active BOOLEAN DEFAULT TRUE NOT NULL,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  updated_at TIMESTAMP WITH TIME ZONE,
  created_by NUMBER(19),
  updated_by NUMBER(19),
  CONSTRAINT pk_attribute_definition PRIMARY KEY (id),
  CONSTRAINT uq_attribute_definition_code UNIQUE (code)
);

CREATE TABLE attribute_option (
  id NUMBER(19) GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  attribute_id NUMBER(19) NOT NULL,
  value VARCHAR2(100 CHAR) NOT NULL,
  display_name VARCHAR2(100 CHAR) NOT NULL,
  sort_order NUMBER(10),
  is_active BOOLEAN DEFAULT TRUE NOT NULL,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  updated_at TIMESTAMP WITH TIME ZONE,
  created_by NUMBER(19),
  updated_by NUMBER(19),
  CONSTRAINT pk_attribute_option PRIMARY KEY (id),
  CONSTRAINT uq_attribute_option_attribute_id_value UNIQUE (attribute_id, value)
);

CREATE TABLE product_attribute_value (
  product_id NUMBER(19) NOT NULL,
  attribute_id NUMBER(19) NOT NULL,
  value_text VARCHAR2(255 CHAR),
  value_number NUMBER(12,3),
  created_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  CONSTRAINT pk_product_attribute_value PRIMARY KEY (product_id, attribute_id),
  CONSTRAINT ck_product_attribute_value_1 CHECK ((value_text IS NOT NULL AND value_number IS NULL) OR (value_text IS NULL AND value_number IS NOT NULL))
);

CREATE TABLE variant_attribute_value (
  variant_id NUMBER(19) NOT NULL,
  attribute_id NUMBER(19) NOT NULL,
  value_text VARCHAR2(255 CHAR),
  value_number NUMBER(12,3),
  created_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  CONSTRAINT pk_variant_attribute_value PRIMARY KEY (variant_id, attribute_id),
  CONSTRAINT ck_variant_attribute_value_1 CHECK ((value_text IS NOT NULL AND value_number IS NULL) OR (value_text IS NULL AND value_number IS NOT NULL))
);

CREATE TABLE price_history (
  id NUMBER(19) GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  variant_id NUMBER(19) NOT NULL,
  price NUMBER(15,2) NOT NULL,
  effective_from TIMESTAMP WITH TIME ZONE NOT NULL,
  effective_to TIMESTAMP WITH TIME ZONE,
  status VARCHAR2(10 CHAR) NOT NULL,
  reason VARCHAR2(255 CHAR),
  created_by NUMBER(19) NOT NULL,
  approved_by NUMBER(19),
  created_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  CONSTRAINT pk_price_history PRIMARY KEY (id),
  CONSTRAINT ck_price_history_1 CHECK (status IN ('PENDING', 'APPROVED', 'CANCELLED')),
  CONSTRAINT ck_price_history_2 CHECK (effective_to IS NULL OR effective_to > effective_from)
);

CREATE TABLE product_group (
  id NUMBER(19) GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  name VARCHAR2(100 CHAR) NOT NULL,
  description VARCHAR2(255 CHAR),
  is_active BOOLEAN DEFAULT TRUE NOT NULL,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  updated_at TIMESTAMP WITH TIME ZONE,
  created_by NUMBER(19),
  updated_by NUMBER(19),
  CONSTRAINT pk_product_group PRIMARY KEY (id),
  CONSTRAINT uq_product_group_name UNIQUE (name)
);

CREATE TABLE product_group_item (
  id NUMBER(19) GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  group_id NUMBER(19) NOT NULL,
  product_id NUMBER(19),
  variant_id NUMBER(19),
  created_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  updated_at TIMESTAMP WITH TIME ZONE,
  created_by NUMBER(19),
  updated_by NUMBER(19),
  CONSTRAINT pk_product_group_item PRIMARY KEY (id),
  CONSTRAINT uq_product_group_item_group_id_product_id_variant_id UNIQUE (group_id, product_id, variant_id),
  CONSTRAINT ck_product_group_item_1 CHECK ((product_id IS NOT NULL AND variant_id IS NULL) OR (product_id IS NULL AND variant_id IS NOT NULL))
);

-- ---------------- Module B: Kho và phân phối (12 bảng) ----------------

CREATE TABLE branch (
  id NUMBER(19) GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  name VARCHAR2(150 CHAR) NOT NULL,
  address VARCHAR2(255 CHAR) NOT NULL,
  phone VARCHAR2(20 CHAR),
  branch_type VARCHAR2(10 CHAR) NOT NULL,
  is_active BOOLEAN DEFAULT TRUE NOT NULL,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  updated_at TIMESTAMP WITH TIME ZONE,
  created_by NUMBER(19),
  updated_by NUMBER(19),
  CONSTRAINT pk_branch PRIMARY KEY (id),
  CONSTRAINT ck_branch_1 CHECK (branch_type IN ('STORE', 'WAREHOUSE'))
);

CREATE TABLE supplier (
  id NUMBER(19) GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  name VARCHAR2(150 CHAR) NOT NULL,
  tax_code VARCHAR2(20 CHAR),
  contact_name VARCHAR2(100 CHAR),
  phone VARCHAR2(20 CHAR),
  address VARCHAR2(255 CHAR),
  is_active BOOLEAN DEFAULT TRUE NOT NULL,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  updated_at TIMESTAMP WITH TIME ZONE,
  created_by NUMBER(19),
  updated_by NUMBER(19),
  CONSTRAINT pk_supplier PRIMARY KEY (id)
);

CREATE TABLE goods_receipt (
  id NUMBER(19) GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  code VARCHAR2(30 CHAR) NOT NULL,
  supplier_id NUMBER(19) NOT NULL,
  branch_id NUMBER(19) NOT NULL,
  received_by NUMBER(19) NOT NULL,
  received_at TIMESTAMP WITH TIME ZONE NOT NULL,
  status VARCHAR2(10 CHAR) NOT NULL,
  note VARCHAR2(255 CHAR),
  created_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  updated_at TIMESTAMP WITH TIME ZONE,
  created_by NUMBER(19),
  updated_by NUMBER(19),
  CONSTRAINT pk_goods_receipt PRIMARY KEY (id),
  CONSTRAINT uq_goods_receipt_code UNIQUE (code)
);

CREATE TABLE goods_receipt_item (
  id NUMBER(19) GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  receipt_id NUMBER(19) NOT NULL,
  variant_id NUMBER(19) NOT NULL,
  quantity NUMBER(10) NOT NULL,
  unit_cost NUMBER(15,2) NOT NULL,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  updated_at TIMESTAMP WITH TIME ZONE,
  created_by NUMBER(19),
  updated_by NUMBER(19),
  CONSTRAINT pk_goods_receipt_item PRIMARY KEY (id),
  CONSTRAINT ck_goods_receipt_item_quantity CHECK (quantity > 0)
);

CREATE TABLE serial_item (
  id NUMBER(19) GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  variant_id NUMBER(19) NOT NULL,
  serial_number VARCHAR2(60 CHAR) NOT NULL,
  branch_id NUMBER(19) NOT NULL,
  status VARCHAR2(12 CHAR) NOT NULL,
  goods_receipt_item_id NUMBER(19),
  cost_price NUMBER(15,2) NOT NULL,
  order_item_id NUMBER(19),
  sold_at TIMESTAMP WITH TIME ZONE,
  warranty_start DATE,
  warranty_end DATE,
  version NUMBER(10) DEFAULT 0 NOT NULL,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  updated_at TIMESTAMP WITH TIME ZONE,
  created_by NUMBER(19),
  updated_by NUMBER(19),
  CONSTRAINT pk_serial_item PRIMARY KEY (id),
  CONSTRAINT uq_serial_item_serial_number UNIQUE (serial_number),
  CONSTRAINT ck_serial_item_1 CHECK (status IN ('IN_STOCK', 'SOLD', 'IN_TRANSIT', 'RETURNED', 'DEFECTIVE', 'WARRANTY'))
);

CREATE TABLE serial_status_history (
  id NUMBER(19) GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  serial_id NUMBER(19) NOT NULL,
  from_status VARCHAR2(12 CHAR),
  to_status VARCHAR2(12 CHAR) NOT NULL,
  from_branch_id NUMBER(19),
  to_branch_id NUMBER(19),
  ref_type VARCHAR2(12 CHAR),
  ref_id NUMBER(19),
  changed_by NUMBER(19),
  changed_at TIMESTAMP WITH TIME ZONE NOT NULL,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  CONSTRAINT pk_serial_status_history PRIMARY KEY (id)
);

CREATE TABLE inventory_balance (
  variant_id NUMBER(19) NOT NULL,
  branch_id NUMBER(19) NOT NULL,
  on_hand NUMBER(10) NOT NULL,
  held_qty NUMBER(10) NOT NULL,
  version NUMBER(10) DEFAULT 0 NOT NULL,
  updated_at TIMESTAMP WITH TIME ZONE,
  CONSTRAINT pk_inventory_balance PRIMARY KEY (variant_id, branch_id),
  CONSTRAINT ck_inventory_balance_on_hand CHECK (on_hand >= 0),
  CONSTRAINT ck_inventory_balance_held_qty CHECK (held_qty >= 0),
  CONSTRAINT ck_inventory_balance_1 CHECK (held_qty <= on_hand)
);

CREATE TABLE stock_hold (
  id NUMBER(19) GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  order_id NUMBER(19),
  order_item_id NUMBER(19),
  variant_id NUMBER(19) NOT NULL,
  branch_id NUMBER(19) NOT NULL,
  hold_type VARCHAR2(10 CHAR) NOT NULL,
  serial_id NUMBER(19),
  quantity NUMBER(10) DEFAULT 1 NOT NULL,
  status VARCHAR2(10 CHAR) NOT NULL,
  held_by NUMBER(19),
  held_at TIMESTAMP WITH TIME ZONE NOT NULL,
  expires_at TIMESTAMP WITH TIME ZONE NOT NULL,
  released_at TIMESTAMP WITH TIME ZONE,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  updated_at TIMESTAMP WITH TIME ZONE,
  created_by NUMBER(19),
  updated_by NUMBER(19),
  CONSTRAINT pk_stock_hold PRIMARY KEY (id),
  CONSTRAINT ck_stock_hold_1 CHECK (status IN ('ACTIVE', 'CONVERTED', 'RELEASED', 'EXPIRED')),
  CONSTRAINT ck_stock_hold_2 CHECK (hold_type IN ('SERIAL', 'QUANTITY')),
  CONSTRAINT ck_stock_hold_3 CHECK (hold_type <> 'SERIAL' OR serial_id IS NOT NULL)
);

CREATE TABLE stock_transfer (
  id NUMBER(19) GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  code VARCHAR2(30 CHAR) NOT NULL,
  from_branch_id NUMBER(19) NOT NULL,
  to_branch_id NUMBER(19) NOT NULL,
  status VARCHAR2(10 CHAR) NOT NULL,
  created_by NUMBER(19),
  shipped_by NUMBER(19),
  received_by NUMBER(19),
  shipped_at TIMESTAMP WITH TIME ZONE,
  received_at TIMESTAMP WITH TIME ZONE,
  note VARCHAR2(255 CHAR),
  created_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  updated_at TIMESTAMP WITH TIME ZONE,
  updated_by NUMBER(19),
  CONSTRAINT pk_stock_transfer PRIMARY KEY (id),
  CONSTRAINT uq_stock_transfer_code UNIQUE (code),
  CONSTRAINT ck_stock_transfer_1 CHECK (status IN ('DRAFT', 'IN_TRANSIT', 'RECEIVED', 'CANCELLED')),
  CONSTRAINT ck_stock_transfer_2 CHECK (from_branch_id <> to_branch_id)
);

CREATE TABLE stock_transfer_item (
  id NUMBER(19) GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  transfer_id NUMBER(19) NOT NULL,
  serial_id NUMBER(19) NOT NULL,
  received_ok BOOLEAN,
  receive_note VARCHAR2(255 CHAR),
  created_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  updated_at TIMESTAMP WITH TIME ZONE,
  created_by NUMBER(19),
  updated_by NUMBER(19),
  CONSTRAINT pk_stock_transfer_item PRIMARY KEY (id),
  CONSTRAINT uq_stock_transfer_item_transfer_id_serial_id UNIQUE (transfer_id, serial_id)
);

CREATE TABLE stocktake (
  id NUMBER(19) GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  code VARCHAR2(30 CHAR) NOT NULL,
  branch_id NUMBER(19) NOT NULL,
  status VARCHAR2(10 CHAR) NOT NULL,
  scope VARCHAR2(100 CHAR),
  started_by NUMBER(19) NOT NULL,
  closed_by NUMBER(19),
  started_at TIMESTAMP WITH TIME ZONE NOT NULL,
  closed_at TIMESTAMP WITH TIME ZONE,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  updated_at TIMESTAMP WITH TIME ZONE,
  created_by NUMBER(19),
  updated_by NUMBER(19),
  CONSTRAINT pk_stocktake PRIMARY KEY (id),
  CONSTRAINT uq_stocktake_code UNIQUE (code)
);

CREATE TABLE stocktake_item (
  id NUMBER(19) GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  stocktake_id NUMBER(19) NOT NULL,
  serial_id NUMBER(19) NOT NULL,
  variant_id NUMBER(19) NOT NULL,
  expected BOOLEAN NOT NULL,
  scanned_at TIMESTAMP WITH TIME ZONE,
  scanned_by NUMBER(19),
  result VARCHAR2(12 CHAR),
  note VARCHAR2(255 CHAR),
  adjusted_by NUMBER(19),
  created_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  updated_at TIMESTAMP WITH TIME ZONE,
  created_by NUMBER(19),
  updated_by NUMBER(19),
  CONSTRAINT pk_stocktake_item PRIMARY KEY (id),
  CONSTRAINT uq_stocktake_item_stocktake_id_serial_id UNIQUE (stocktake_id, serial_id)
);

-- ---------------- Module C: Bán hàng, giảm giá, thanh toán, giao hàng (17 bảng) ----------------

CREATE TABLE customer (
  id NUMBER(19) GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  phone VARCHAR2(20 CHAR) NOT NULL,
  full_name VARCHAR2(120 CHAR) NOT NULL,
  email VARCHAR2(120 CHAR),
  password_hash VARCHAR2(100 CHAR),
  email_verified_at TIMESTAMP WITH TIME ZONE,
  registered_at TIMESTAMP WITH TIME ZONE,
  first_order_at TIMESTAMP WITH TIME ZONE,
  last_order_at TIMESTAMP WITH TIME ZONE,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  updated_at TIMESTAMP WITH TIME ZONE,
  created_by NUMBER(19),
  updated_by NUMBER(19),
  CONSTRAINT pk_customer PRIMARY KEY (id),
  CONSTRAINT uq_customer_phone UNIQUE (phone)
);

CREATE TABLE customer_address (
  id NUMBER(19) GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  customer_id NUMBER(19) NOT NULL,
  receiver_name VARCHAR2(120 CHAR) NOT NULL,
  receiver_phone VARCHAR2(20 CHAR) NOT NULL,
  province_code VARCHAR2(20 CHAR) NOT NULL,
  district_code VARCHAR2(20 CHAR) NOT NULL,
  ward_code VARCHAR2(20 CHAR) NOT NULL,
  address_line VARCHAR2(255 CHAR) NOT NULL,
  is_default BOOLEAN DEFAULT FALSE NOT NULL,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  updated_at TIMESTAMP WITH TIME ZONE,
  created_by NUMBER(19),
  updated_by NUMBER(19),
  CONSTRAINT pk_customer_address PRIMARY KEY (id)
);

CREATE TABLE cart (
  id NUMBER(19) GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  cart_token CHAR(36) NOT NULL,
  customer_id NUMBER(19),
  status VARCHAR2(10 CHAR) NOT NULL,
  expires_at TIMESTAMP WITH TIME ZONE,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  updated_at TIMESTAMP WITH TIME ZONE,
  created_by NUMBER(19),
  updated_by NUMBER(19),
  CONSTRAINT pk_cart PRIMARY KEY (id),
  CONSTRAINT uq_cart_cart_token UNIQUE (cart_token)
);

CREATE TABLE cart_item (
  id NUMBER(19) GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  cart_id NUMBER(19) NOT NULL,
  variant_id NUMBER(19) NOT NULL,
  quantity NUMBER(10) NOT NULL,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  updated_at TIMESTAMP WITH TIME ZONE,
  created_by NUMBER(19),
  updated_by NUMBER(19),
  CONSTRAINT pk_cart_item PRIMARY KEY (id),
  CONSTRAINT ck_cart_item_quantity CHECK (quantity > 0),
  CONSTRAINT uq_cart_item_cart_id_variant_id UNIQUE (cart_id, variant_id)
);

CREATE TABLE customer_order (
  id NUMBER(19) GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  order_code VARCHAR2(30 CHAR) NOT NULL,
  channel VARCHAR2(8 CHAR) NOT NULL,
  status VARCHAR2(12 CHAR) NOT NULL,
  customer_id NUMBER(19),
  customer_name VARCHAR2(120 CHAR) NOT NULL,
  customer_phone VARCHAR2(20 CHAR) NOT NULL,
  customer_email VARCHAR2(120 CHAR),
  fulfillment_method VARCHAR2(10 CHAR) NOT NULL,
  desired_receipt_date DATE,
  ship_province_code VARCHAR2(20 CHAR),
  ship_district_code VARCHAR2(20 CHAR),
  ship_ward_code VARCHAR2(20 CHAR),
  ship_address_line VARCHAR2(255 CHAR),
  note VARCHAR2(255 CHAR),
  fulfill_branch_id NUMBER(19),
  created_by NUMBER(19),
  handled_by NUMBER(19),
  confirmed_by NUMBER(19),
  confirmed_at TIMESTAMP WITH TIME ZONE,
  shift_assignment_id NUMBER(19),
  subtotal NUMBER(15,2) NOT NULL,
  discount_total NUMBER(15,2) DEFAULT 0 NOT NULL,
  shipping_fee NUMBER(15,2) DEFAULT 0 NOT NULL,
  total_amount NUMBER(15,2) NOT NULL,
  payment_status VARCHAR2(10 CHAR) NOT NULL,
  placed_at TIMESTAMP WITH TIME ZONE NOT NULL,
  completed_at TIMESTAMP WITH TIME ZONE,
  cancel_reason VARCHAR2(255 CHAR),
  version NUMBER(10) DEFAULT 0 NOT NULL,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  updated_at TIMESTAMP WITH TIME ZONE,
  updated_by NUMBER(19),
  CONSTRAINT pk_customer_order PRIMARY KEY (id),
  CONSTRAINT uq_customer_order_order_code UNIQUE (order_code),
  CONSTRAINT ck_customer_order_1 CHECK (status IN ('DRAFT', 'NEW', 'CONFIRMED', 'PREPARING', 'SHIPPING', 'COMPLETED', 'CANCELLED')),
  CONSTRAINT ck_customer_order_2 CHECK (channel IN ('ONLINE', 'COUNTER')),
  CONSTRAINT ck_customer_order_3 CHECK (fulfillment_method IN ('PICKUP', 'DELIVERY'))
);

CREATE TABLE order_item (
  id NUMBER(19) GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  order_id NUMBER(19) NOT NULL,
  variant_id NUMBER(19) NOT NULL,
  quantity NUMBER(10) NOT NULL,
  unit_price NUMBER(15,2) NOT NULL,
  price_history_id NUMBER(19) NOT NULL,
  priced_at TIMESTAMP WITH TIME ZONE NOT NULL,
  line_discount NUMBER(15,2) DEFAULT 0 NOT NULL,
  line_total NUMBER(15,2) NOT NULL,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  updated_at TIMESTAMP WITH TIME ZONE,
  created_by NUMBER(19),
  updated_by NUMBER(19),
  CONSTRAINT pk_order_item PRIMARY KEY (id),
  CONSTRAINT ck_order_item_quantity CHECK (quantity > 0)
);

CREATE TABLE order_status_history (
  id NUMBER(19) GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  order_id NUMBER(19) NOT NULL,
  from_status VARCHAR2(12 CHAR),
  to_status VARCHAR2(12 CHAR) NOT NULL,
  changed_by NUMBER(19),
  changed_at TIMESTAMP WITH TIME ZONE NOT NULL,
  reason VARCHAR2(255 CHAR),
  created_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  CONSTRAINT pk_order_status_history PRIMARY KEY (id)
);

CREATE TABLE campaign (
  id NUMBER(19) GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  code VARCHAR2(30 CHAR) NOT NULL,
  name VARCHAR2(150 CHAR) NOT NULL,
  discount_type VARCHAR2(12 CHAR) NOT NULL,
  discount_value NUMBER(15,2) NOT NULL,
  max_discount NUMBER(15,2),
  min_order_value NUMBER(15,2) DEFAULT 0 NOT NULL,
  priority NUMBER(10) NOT NULL,
  is_stackable BOOLEAN NOT NULL,
  status VARCHAR2(10 CHAR) NOT NULL,
  start_at TIMESTAMP WITH TIME ZONE NOT NULL,
  end_at TIMESTAMP WITH TIME ZONE NOT NULL,
  created_by NUMBER(19),
  approved_by NUMBER(19),
  version NUMBER(10) DEFAULT 0 NOT NULL,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  updated_at TIMESTAMP WITH TIME ZONE,
  updated_by NUMBER(19),
  CONSTRAINT pk_campaign PRIMARY KEY (id),
  CONSTRAINT uq_campaign_code UNIQUE (code),
  CONSTRAINT ck_campaign_1 CHECK (status IN ('DRAFT', 'SCHEDULED', 'ACTIVE', 'ENDED', 'CANCELLED')),
  CONSTRAINT ck_campaign_2 CHECK (discount_type IN ('PERCENT', 'AMOUNT', 'FIXED_PRICE')),
  CONSTRAINT ck_campaign_3 CHECK (end_at > start_at)
);

CREATE TABLE campaign_scope (
  id NUMBER(19) GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  owner_type VARCHAR2(10 CHAR) NOT NULL,
  owner_id NUMBER(19) NOT NULL,
  scope_type VARCHAR2(10 CHAR) NOT NULL,
  target_id NUMBER(19),
  is_exclude BOOLEAN DEFAULT FALSE NOT NULL,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  updated_at TIMESTAMP WITH TIME ZONE,
  created_by NUMBER(19),
  updated_by NUMBER(19),
  CONSTRAINT pk_campaign_scope PRIMARY KEY (id),
  CONSTRAINT ck_campaign_scope_1 CHECK (owner_type IN ('CAMPAIGN', 'VOUCHER')),
  CONSTRAINT ck_campaign_scope_2 CHECK (scope_type IN ('ALL', 'BRAND', 'CATEGORY', 'GROUP', 'PRODUCT', 'VARIANT'))
);

CREATE TABLE voucher (
  id NUMBER(19) GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  code VARCHAR2(30 CHAR) NOT NULL,
  name VARCHAR2(150 CHAR) NOT NULL,
  audience VARCHAR2(10 CHAR) NOT NULL,
  discount_type VARCHAR2(10 CHAR) NOT NULL,
  discount_value NUMBER(15,2) NOT NULL,
  max_discount NUMBER(15,2),
  min_order NUMBER(15,2) DEFAULT 0 NOT NULL,
  total_limit NUMBER(10),
  per_customer_limit NUMBER(10) DEFAULT 1,
  used_count NUMBER(10) DEFAULT 0 NOT NULL,
  reserved_count NUMBER(10) DEFAULT 0 NOT NULL,
  stackable_with_campaign BOOLEAN NOT NULL,
  start_at TIMESTAMP WITH TIME ZONE NOT NULL,
  end_at TIMESTAMP WITH TIME ZONE NOT NULL,
  status VARCHAR2(10 CHAR) NOT NULL,
  version NUMBER(10) DEFAULT 0 NOT NULL,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  updated_at TIMESTAMP WITH TIME ZONE,
  created_by NUMBER(19),
  updated_by NUMBER(19),
  CONSTRAINT pk_voucher PRIMARY KEY (id),
  CONSTRAINT uq_voucher_code UNIQUE (code),
  CONSTRAINT ck_voucher_1 CHECK (audience IN ('PUBLIC', 'PERSONAL')),
  CONSTRAINT ck_voucher_2 CHECK (end_at > start_at),
  CONSTRAINT ck_voucher_3 CHECK (total_limit IS NULL OR used_count + reserved_count <= total_limit)
);

CREATE TABLE voucher_customer (
  id NUMBER(19) GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  voucher_id NUMBER(19) NOT NULL,
  customer_id NUMBER(19) NOT NULL,
  assigned_by NUMBER(19),
  assigned_at TIMESTAMP WITH TIME ZONE NOT NULL,
  expires_at TIMESTAMP WITH TIME ZONE,
  status VARCHAR2(10 CHAR) NOT NULL,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  updated_at TIMESTAMP WITH TIME ZONE,
  created_by NUMBER(19),
  updated_by NUMBER(19),
  CONSTRAINT pk_voucher_customer PRIMARY KEY (id),
  CONSTRAINT uq_voucher_customer_voucher_id_customer_id UNIQUE (voucher_id, customer_id)
);

CREATE TABLE voucher_redemption (
  id NUMBER(19) GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  voucher_id NUMBER(19) NOT NULL,
  order_id NUMBER(19) NOT NULL,
  customer_id NUMBER(19),
  customer_phone VARCHAR2(20 CHAR) NOT NULL,
  status VARCHAR2(10 CHAR) NOT NULL,
  discount_amount NUMBER(15,2),
  reserved_at TIMESTAMP WITH TIME ZONE NOT NULL,
  used_at TIMESTAMP WITH TIME ZONE,
  expires_at TIMESTAMP WITH TIME ZONE,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  updated_at TIMESTAMP WITH TIME ZONE,
  created_by NUMBER(19),
  updated_by NUMBER(19),
  CONSTRAINT pk_voucher_redemption PRIMARY KEY (id),
  CONSTRAINT uq_voucher_redemption_voucher_id_order_id UNIQUE (voucher_id, order_id),
  CONSTRAINT ck_voucher_redemption_1 CHECK (status IN ('RESERVED', 'USED', 'RELEASED'))
);

CREATE TABLE order_discount_line (
  id NUMBER(19) GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  order_id NUMBER(19) NOT NULL,
  order_item_id NUMBER(19),
  source_type VARCHAR2(10 CHAR) NOT NULL,
  source_id NUMBER(19),
  name_snapshot VARCHAR2(150 CHAR) NOT NULL,
  rule_snapshot JSON,
  amount NUMBER(15,2) NOT NULL,
  reason VARCHAR2(255 CHAR),
  created_by NUMBER(19),
  approved_by NUMBER(19),
  created_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  updated_at TIMESTAMP WITH TIME ZONE,
  updated_by NUMBER(19),
  CONSTRAINT pk_order_discount_line PRIMARY KEY (id)
);

CREATE TABLE payment (
  id NUMBER(19) GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  order_id NUMBER(19) NOT NULL,
  method VARCHAR2(14 CHAR) NOT NULL,
  payment_type VARCHAR2(8 CHAR) NOT NULL,
  amount NUMBER(15,2) NOT NULL,
  tendered_amount NUMBER(15,2),
  change_amount NUMBER(15,2),
  status VARCHAR2(10 CHAR) NOT NULL,
  reference_code VARCHAR2(60 CHAR),
  received_by NUMBER(19),
  paid_at TIMESTAMP WITH TIME ZONE,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  updated_at TIMESTAMP WITH TIME ZONE,
  created_by NUMBER(19),
  updated_by NUMBER(19),
  CONSTRAINT pk_payment PRIMARY KEY (id),
  CONSTRAINT ck_payment_amount CHECK (amount > 0),
  CONSTRAINT ck_payment_1 CHECK (method IN ('CASH', 'BANK_TRANSFER', 'CARD_POS', 'COD')),
  CONSTRAINT ck_payment_2 CHECK (payment_type IN ('DEPOSIT', 'FULL', 'BALANCE'))
);

CREATE TABLE refund (
  id NUMBER(19) GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  payment_id NUMBER(19) NOT NULL,
  order_id NUMBER(19) NOT NULL,
  return_request_id NUMBER(19),
  amount NUMBER(15,2) NOT NULL,
  method VARCHAR2(14 CHAR) NOT NULL,
  status VARCHAR2(10 CHAR) NOT NULL,
  reason VARCHAR2(255 CHAR),
  approved_by NUMBER(19),
  processed_at TIMESTAMP WITH TIME ZONE,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  updated_at TIMESTAMP WITH TIME ZONE,
  created_by NUMBER(19),
  updated_by NUMBER(19),
  CONSTRAINT pk_refund PRIMARY KEY (id),
  CONSTRAINT ck_refund_amount CHECK (amount > 0)
);

CREATE TABLE delivery (
  id NUMBER(19) GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  order_id NUMBER(19) NOT NULL,
  carrier_code VARCHAR2(20 CHAR),
  carrier_order_code VARCHAR2(60 CHAR),
  tracking_code VARCHAR2(60 CHAR),
  status VARCHAR2(12 CHAR) NOT NULL,
  receiver_name VARCHAR2(120 CHAR) NOT NULL,
  receiver_phone VARCHAR2(20 CHAR) NOT NULL,
  receiver_address VARCHAR2(255 CHAR) NOT NULL,
  shipping_fee NUMBER(15,2),
  shipping_fee_source VARCHAR2(8 CHAR),
  cod_amount NUMBER(15,2),
  expected_delivery_at TIMESTAMP WITH TIME ZONE,
  shipped_at TIMESTAMP WITH TIME ZONE,
  delivered_at TIMESTAMP WITH TIME ZONE,
  handled_by NUMBER(19),
  created_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  updated_at TIMESTAMP WITH TIME ZONE,
  created_by NUMBER(19),
  updated_by NUMBER(19),
  CONSTRAINT pk_delivery PRIMARY KEY (id),
  CONSTRAINT uq_delivery_order_id UNIQUE (order_id)
);

CREATE TABLE invoice (
  id NUMBER(19) GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  invoice_no VARCHAR2(20 CHAR) NOT NULL,
  order_id NUMBER(19) NOT NULL,
  issued_at TIMESTAMP WITH TIME ZONE NOT NULL,
  issued_by NUMBER(19) NOT NULL,
  buyer_name VARCHAR2(150 CHAR) NOT NULL,
  buyer_tax_code VARCHAR2(20 CHAR),
  buyer_address VARCHAR2(255 CHAR),
  total_amount NUMBER(15,2) NOT NULL,
  pdf_url VARCHAR2(255 CHAR),
  status VARCHAR2(10 CHAR) NOT NULL,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  updated_at TIMESTAMP WITH TIME ZONE,
  created_by NUMBER(19),
  updated_by NUMBER(19),
  CONSTRAINT pk_invoice PRIMARY KEY (id),
  CONSTRAINT uq_invoice_invoice_no UNIQUE (invoice_no)
);

-- ---------------- Module D: Hậu mãi (3 bảng) ----------------

CREATE TABLE return_request (
  id NUMBER(19) GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  code VARCHAR2(30 CHAR) NOT NULL,
  order_id NUMBER(19) NOT NULL,
  customer_id NUMBER(19),
  request_type VARCHAR2(10 CHAR) NOT NULL,
  reason VARCHAR2(255 CHAR) NOT NULL,
  status VARCHAR2(10 CHAR) NOT NULL,
  requested_at TIMESTAMP WITH TIME ZONE NOT NULL,
  approved_by NUMBER(19),
  resolved_at TIMESTAMP WITH TIME ZONE,
  resolution_note VARCHAR2(255 CHAR),
  created_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  updated_at TIMESTAMP WITH TIME ZONE,
  created_by NUMBER(19),
  updated_by NUMBER(19),
  CONSTRAINT pk_return_request PRIMARY KEY (id),
  CONSTRAINT uq_return_request_code UNIQUE (code),
  CONSTRAINT ck_return_request_1 CHECK (status IN ('REQUESTED', 'APPROVED', 'RECEIVED', 'COMPLETED', 'REJECTED'))
);

CREATE TABLE return_request_item (
  id NUMBER(19) GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  return_request_id NUMBER(19) NOT NULL,
  serial_id NUMBER(19) NOT NULL,
  order_item_id NUMBER(19) NOT NULL,
  condition VARCHAR2(10 CHAR) NOT NULL,
  restock_decision VARCHAR2(10 CHAR),
  refund_amount NUMBER(15,2),
  created_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  updated_at TIMESTAMP WITH TIME ZONE,
  created_by NUMBER(19),
  updated_by NUMBER(19),
  CONSTRAINT pk_return_request_item PRIMARY KEY (id)
);

CREATE TABLE warranty_claim (
  id NUMBER(19) GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  code VARCHAR2(30 CHAR) NOT NULL,
  serial_id NUMBER(19) NOT NULL,
  customer_id NUMBER(19),
  issue_description CLOB NOT NULL,
  received_at TIMESTAMP WITH TIME ZONE NOT NULL,
  in_warranty BOOLEAN NOT NULL,
  status VARCHAR2(14 CHAR) NOT NULL,
  handled_by NUMBER(19),
  resolution VARCHAR2(255 CHAR),
  repair_cost NUMBER(15,2),
  completed_at TIMESTAMP WITH TIME ZONE,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  updated_at TIMESTAMP WITH TIME ZONE,
  created_by NUMBER(19),
  updated_by NUMBER(19),
  CONSTRAINT pk_warranty_claim PRIMARY KEY (id),
  CONSTRAINT uq_warranty_claim_code UNIQUE (code),
  CONSTRAINT ck_warranty_claim_1 CHECK (status IN ('RECEIVED', 'DIAGNOSING', 'REPAIRING', 'WAITING_PARTS', 'DONE', 'RETURNED', 'REJECTED'))
);

-- ---------------- Module E: Nhân sự và phân quyền (9 bảng) ----------------

CREATE TABLE app_user (
  id NUMBER(19) GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  username VARCHAR2(50 CHAR) NOT NULL,
  password_hash VARCHAR2(100 CHAR) NOT NULL,
  full_name VARCHAR2(120 CHAR) NOT NULL,
  email VARCHAR2(120 CHAR),
  phone VARCHAR2(20 CHAR),
  gender VARCHAR2(8 CHAR),
  date_of_birth DATE,
  citizen_id VARCHAR2(20 CHAR),
  avatar_url VARCHAR2(255 CHAR),
  branch_id NUMBER(19),
  auth_provider VARCHAR2(10 CHAR) DEFAULT 'LOCAL',
  provider_subject VARCHAR2(100 CHAR),
  is_active BOOLEAN DEFAULT TRUE NOT NULL,
  failed_login_count NUMBER(10) DEFAULT 0,
  locked_until TIMESTAMP WITH TIME ZONE,
  last_login_at TIMESTAMP WITH TIME ZONE,
  deleted_at TIMESTAMP WITH TIME ZONE,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  updated_at TIMESTAMP WITH TIME ZONE,
  created_by NUMBER(19),
  updated_by NUMBER(19),
  CONSTRAINT pk_app_user PRIMARY KEY (id),
  CONSTRAINT uq_app_user_username UNIQUE (username),
  CONSTRAINT uq_app_user_email UNIQUE (email),
  CONSTRAINT uq_app_user_citizen_id UNIQUE (citizen_id)
);

CREATE TABLE role (
  id NUMBER(19) GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  code VARCHAR2(30 CHAR) NOT NULL,
  name VARCHAR2(80 CHAR) NOT NULL,
  description VARCHAR2(255 CHAR),
  is_system BOOLEAN DEFAULT FALSE NOT NULL,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  updated_at TIMESTAMP WITH TIME ZONE,
  created_by NUMBER(19),
  updated_by NUMBER(19),
  CONSTRAINT pk_role PRIMARY KEY (id),
  CONSTRAINT uq_role_code UNIQUE (code)
);

CREATE TABLE permission (
  id NUMBER(19) GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  code VARCHAR2(50 CHAR) NOT NULL,
  name VARCHAR2(100 CHAR) NOT NULL,
  module VARCHAR2(30 CHAR) NOT NULL,
  portal VARCHAR2(20 CHAR),
  created_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  updated_at TIMESTAMP WITH TIME ZONE,
  created_by NUMBER(19),
  updated_by NUMBER(19),
  CONSTRAINT pk_permission PRIMARY KEY (id),
  CONSTRAINT uq_permission_code UNIQUE (code)
);

CREATE TABLE role_permission (
  role_id NUMBER(19) NOT NULL,
  permission_id NUMBER(19) NOT NULL,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  CONSTRAINT pk_role_permission PRIMARY KEY (role_id, permission_id)
);

CREATE TABLE user_role (
  id NUMBER(19) GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  user_id NUMBER(19) NOT NULL,
  role_id NUMBER(19) NOT NULL,
  branch_id NUMBER(19),
  granted_by NUMBER(19),
  granted_at TIMESTAMP WITH TIME ZONE NOT NULL,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  CONSTRAINT pk_user_role PRIMARY KEY (id),
  CONSTRAINT uq_user_role_user_id_role_id_branch_id UNIQUE (user_id, role_id, branch_id)
);

CREATE TABLE shift_template (
  id NUMBER(19) GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  branch_id NUMBER(19),
  name VARCHAR2(50 CHAR) NOT NULL,
  start_time VARCHAR2(5 CHAR) NOT NULL,
  end_time VARCHAR2(5 CHAR) NOT NULL,
  is_active BOOLEAN DEFAULT TRUE NOT NULL,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  updated_at TIMESTAMP WITH TIME ZONE,
  created_by NUMBER(19),
  updated_by NUMBER(19),
  CONSTRAINT pk_shift_template PRIMARY KEY (id),
  CONSTRAINT ck_shift_template_1 CHECK (REGEXP_LIKE(start_time, '^([01][0-9]|2[0-3]):[0-5][0-9]$') AND REGEXP_LIKE(end_time, '^([01][0-9]|2[0-3]):[0-5][0-9]$'))
);

CREATE TABLE shift_assignment (
  id NUMBER(19) GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  staff_id NUMBER(19) NOT NULL,
  shift_template_id NUMBER(19) NOT NULL,
  branch_id NUMBER(19) NOT NULL,
  work_date DATE NOT NULL,
  status VARCHAR2(10 CHAR) NOT NULL,
  assigned_by NUMBER(19),
  created_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  updated_at TIMESTAMP WITH TIME ZONE,
  created_by NUMBER(19),
  updated_by NUMBER(19),
  CONSTRAINT pk_shift_assignment PRIMARY KEY (id),
  CONSTRAINT uq_shift_assignment_staff_id_work_date_shift_template_id UNIQUE (staff_id, work_date, shift_template_id),
  CONSTRAINT ck_shift_assignment_1 CHECK (status IN ('SCHEDULED', 'COMPLETED', 'ABSENT', 'CANCELLED'))
);

CREATE TABLE attendance (
  id NUMBER(19) GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  assignment_id NUMBER(19) NOT NULL,
  check_in TIMESTAMP WITH TIME ZONE,
  check_out TIMESTAMP WITH TIME ZONE,
  late_minutes NUMBER(10) DEFAULT 0,
  note VARCHAR2(255 CHAR),
  adjusted_by NUMBER(19),
  created_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  updated_at TIMESTAMP WITH TIME ZONE,
  created_by NUMBER(19),
  updated_by NUMBER(19),
  CONSTRAINT pk_attendance PRIMARY KEY (id),
  CONSTRAINT uq_attendance_assignment_id UNIQUE (assignment_id)
);

CREATE TABLE leave_request (
  id NUMBER(19) GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  staff_id NUMBER(19) NOT NULL,
  shift_assignment_id NUMBER(19),
  date_from DATE NOT NULL,
  date_to DATE NOT NULL,
  reason VARCHAR2(255 CHAR) NOT NULL,
  status VARCHAR2(10 CHAR) NOT NULL,
  approved_by NUMBER(19),
  created_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  updated_at TIMESTAMP WITH TIME ZONE,
  created_by NUMBER(19),
  updated_by NUMBER(19),
  CONSTRAINT pk_leave_request PRIMARY KEY (id),
  CONSTRAINT ck_leave_request_1 CHECK (status IN ('PENDING', 'APPROVED', 'REJECTED')),
  CONSTRAINT ck_leave_request_2 CHECK (date_to >= date_from)
);

-- ---------------- Module F: Chat và AI (4 bảng) ----------------

CREATE TABLE chat_session (
  id NUMBER(19) GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  session_token CHAR(36) NOT NULL,
  chat_type VARCHAR2(6 CHAR) NOT NULL,
  customer_id NUMBER(19),
  guest_name VARCHAR2(120 CHAR),
  guest_phone VARCHAR2(20 CHAR),
  assigned_staff_id NUMBER(19),
  status VARCHAR2(8 CHAR) NOT NULL,
  handed_over_from_ai BOOLEAN DEFAULT FALSE,
  closed_at TIMESTAMP WITH TIME ZONE,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  updated_at TIMESTAMP WITH TIME ZONE,
  created_by NUMBER(19),
  updated_by NUMBER(19),
  CONSTRAINT pk_chat_session PRIMARY KEY (id),
  CONSTRAINT uq_chat_session_session_token UNIQUE (session_token)
);

CREATE TABLE chat_message (
  id NUMBER(19) GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  session_id NUMBER(19) NOT NULL,
  sender_type VARCHAR2(6 CHAR) NOT NULL,
  sender_id NUMBER(19),
  content CLOB NOT NULL,
  content_type VARCHAR2(12 CHAR) DEFAULT 'TEXT',
  sent_at TIMESTAMP WITH TIME ZONE NOT NULL,
  read_at TIMESTAMP WITH TIME ZONE,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  updated_at TIMESTAMP WITH TIME ZONE,
  created_by NUMBER(19),
  updated_by NUMBER(19),
  CONSTRAINT pk_chat_message PRIMARY KEY (id)
);

CREATE TABLE consultation_request (
  id NUMBER(19) GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  customer_name VARCHAR2(120 CHAR) NOT NULL,
  phone VARCHAR2(20 CHAR) NOT NULL,
  product_id NUMBER(19),
  variant_id NUMBER(19),
  question CLOB,
  status VARCHAR2(10 CHAR) NOT NULL,
  assigned_to NUMBER(19),
  chat_session_id NUMBER(19),
  created_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  updated_at TIMESTAMP WITH TIME ZONE,
  created_by NUMBER(19),
  updated_by NUMBER(19),
  CONSTRAINT pk_consultation_request PRIMARY KEY (id)
);

CREATE TABLE ai_tool_call_log (
  id NUMBER(19) GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  chat_session_id NUMBER(19) NOT NULL,
  message_id NUMBER(19),
  tool_name VARCHAR2(60 CHAR) NOT NULL,
  arguments JSON,
  result_summary VARCHAR2(500 CHAR),
  status VARCHAR2(6 CHAR) NOT NULL,
  latency_ms NUMBER(10),
  created_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  CONSTRAINT pk_ai_tool_call_log PRIMARY KEY (id)
);

-- ---------------- Module G: Hệ thống và báo cáo (9 bảng) ----------------

CREATE TABLE daily_sales_summary (
  id NUMBER(19) GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  report_date DATE NOT NULL,
  branch_id NUMBER(19) NOT NULL,
  total_orders NUMBER(10) DEFAULT 0,
  cancelled_orders NUMBER(10) DEFAULT 0,
  returned_orders NUMBER(10) DEFAULT 0,
  total_units NUMBER(10) DEFAULT 0,
  gross_revenue NUMBER(17,2) DEFAULT 0,
  discount_total NUMBER(17,2) DEFAULT 0,
  refund_total NUMBER(17,2) DEFAULT 0,
  net_revenue NUMBER(17,2) DEFAULT 0,
  cost NUMBER(17,2) DEFAULT 0,
  profit NUMBER(17,2) DEFAULT 0,
  generated_at TIMESTAMP WITH TIME ZONE,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  updated_at TIMESTAMP WITH TIME ZONE,
  created_by NUMBER(19),
  updated_by NUMBER(19),
  CONSTRAINT pk_daily_sales_summary PRIMARY KEY (id),
  CONSTRAINT uq_daily_sales_summary_report_date_branch_id UNIQUE (report_date, branch_id)
);

CREATE TABLE daily_variant_sales (
  id NUMBER(19) GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  report_date DATE NOT NULL,
  variant_id NUMBER(19) NOT NULL,
  branch_id NUMBER(19) NOT NULL,
  units_sold NUMBER(10) DEFAULT 0,
  units_returned NUMBER(10) DEFAULT 0,
  revenue NUMBER(17,2) DEFAULT 0,
  cost NUMBER(17,2) DEFAULT 0,
  profit NUMBER(17,2) DEFAULT 0,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  updated_at TIMESTAMP WITH TIME ZONE,
  created_by NUMBER(19),
  updated_by NUMBER(19),
  CONSTRAINT pk_daily_variant_sales PRIMARY KEY (id),
  CONSTRAINT uq_daily_variant_sales_report_date_variant_id_branch_id UNIQUE (report_date, variant_id, branch_id)
);

CREATE TABLE audit_log (
  id NUMBER(19) GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  user_id NUMBER(19),
  portal VARCHAR2(20 CHAR),
  action VARCHAR2(50 CHAR) NOT NULL,
  entity_type VARCHAR2(40 CHAR) NOT NULL,
  entity_id NUMBER(19),
  old_value JSON,
  new_value JSON,
  ip_address VARCHAR2(45 CHAR),
  created_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  CONSTRAINT pk_audit_log PRIMARY KEY (id)
);

CREATE TABLE notification_log (
  id NUMBER(19) GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  channel VARCHAR2(8 CHAR) NOT NULL,
  recipient VARCHAR2(150 CHAR) NOT NULL,
  template_code VARCHAR2(40 CHAR) NOT NULL,
  ref_type VARCHAR2(20 CHAR),
  ref_id NUMBER(19),
  status VARCHAR2(8 CHAR) NOT NULL,
  retry_count NUMBER(10) DEFAULT 0,
  error_message VARCHAR2(500 CHAR),
  sent_at TIMESTAMP WITH TIME ZONE,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  CONSTRAINT pk_notification_log PRIMARY KEY (id),
  CONSTRAINT ck_notification_log_1 CHECK (channel IN ('EMAIL', 'SMS', 'IN_APP')),
  CONSTRAINT ck_notification_log_2 CHECK (status IN ('PENDING', 'SENT', 'FAILED'))
);

CREATE TABLE system_setting (
  setting_key VARCHAR2(80 CHAR) NOT NULL,
  setting_value VARCHAR2(500 CHAR) NOT NULL,
  value_type VARCHAR2(10 CHAR) NOT NULL,
  description VARCHAR2(255 CHAR),
  updated_by NUMBER(19),
  updated_at TIMESTAMP WITH TIME ZONE,
  CONSTRAINT pk_system_setting PRIMARY KEY (setting_key)
);

CREATE TABLE otp_verification (
  id NUMBER(19) GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  phone VARCHAR2(20 CHAR) NOT NULL,
  purpose VARCHAR2(10 CHAR) NOT NULL,
  code_hash VARCHAR2(100 CHAR) NOT NULL,
  attempts NUMBER(10) DEFAULT 0,
  expires_at TIMESTAMP WITH TIME ZONE NOT NULL,
  verified_at TIMESTAMP WITH TIME ZONE,
  ip_address VARCHAR2(45 CHAR),
  created_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  updated_at TIMESTAMP WITH TIME ZONE,
  created_by NUMBER(19),
  updated_by NUMBER(19),
  CONSTRAINT pk_otp_verification PRIMARY KEY (id)
);

CREATE TABLE user_notification (
  id NUMBER(19) GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  user_id NUMBER(19) NOT NULL,
  type VARCHAR2(30 CHAR) NOT NULL,
  title VARCHAR2(150 CHAR) NOT NULL,
  body VARCHAR2(500 CHAR),
  ref_type VARCHAR2(20 CHAR),
  ref_id NUMBER(19),
  is_read BOOLEAN DEFAULT FALSE NOT NULL,
  read_at TIMESTAMP WITH TIME ZONE,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  updated_at TIMESTAMP WITH TIME ZONE,
  created_by NUMBER(19),
  updated_by NUMBER(19),
  CONSTRAINT pk_user_notification PRIMARY KEY (id)
);

CREATE TABLE data_transfer_job (
  id NUMBER(19) GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  job_type VARCHAR2(6 CHAR) NOT NULL,
  entity_type VARCHAR2(20 CHAR) NOT NULL,
  file_name VARCHAR2(200 CHAR) NOT NULL,
  status VARCHAR2(8 CHAR) NOT NULL,
  total_rows NUMBER(10) DEFAULT 0,
  success_rows NUMBER(10) DEFAULT 0,
  error_rows NUMBER(10) DEFAULT 0,
  branch_id NUMBER(19),
  created_by NUMBER(19) NOT NULL,
  finished_at TIMESTAMP WITH TIME ZONE,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  updated_at TIMESTAMP WITH TIME ZONE,
  updated_by NUMBER(19),
  CONSTRAINT pk_data_transfer_job PRIMARY KEY (id),
  CONSTRAINT ck_data_transfer_job_1 CHECK (status IN ('PENDING', 'RUNNING', 'DONE', 'PARTIAL', 'FAILED'))
);

CREATE TABLE data_transfer_job_row (
  id NUMBER(19) GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  job_id NUMBER(19) NOT NULL,
  row_no NUMBER(10) NOT NULL,
  status VARCHAR2(8 CHAR) NOT NULL,
  message VARCHAR2(500 CHAR),
  raw_data JSON,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  CONSTRAINT pk_data_transfer_job_row PRIMARY KEY (id)
);

