-- Vai trò -> quyền
INSERT INTO role_permission (role_id, permission_id)
SELECT r.id, p.id FROM role r JOIN permission p ON p.code IN
  ('PORTAL_SALES','ORDER_COUNTER_CREATE','ORDER_FULFILL','ORDER_CANCEL','DISCOUNT_MANUAL')
WHERE r.code = 'SALES';

INSERT INTO role_permission (role_id, permission_id)
SELECT r.id, p.id FROM role r JOIN permission p ON p.code IN ('PORTAL_CONSULT','CHAT_REPLY')
WHERE r.code = 'CONSULTANT';

INSERT INTO role_permission (role_id, permission_id)
SELECT r.id, p.id FROM role r JOIN permission p ON p.code IN
  ('PORTAL_WAREHOUSE','STOCK_RECEIVE','STOCK_TRANSFER','CAMPAIGN_MANAGE','VOUCHER_MANAGE','PRICE_PROPOSE')
WHERE r.code = 'WAREHOUSE_PROMO';

-- ADMIN có mọi quyền (kể cả quyền thêm sau này: viết migration mới để gán)
INSERT INTO role_permission (role_id, permission_id)
SELECT r.id, p.id FROM role r CROSS JOIN permission p WHERE r.code = 'ADMIN';

